import{_ as t,I as a,g as o,j as i}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Ambassador Module","description":"Promotion, smart link generation, receipt QR codes, campaign CRM, and AI marketing assistant.","frontmatter":{"title":"Ambassador Module","description":"Promotion, smart link generation, receipt QR codes, campaign CRM, and AI marketing assistant.","order":17},"headers":[],"relativePath":"docs/spaces/ambassador.md","filePath":"docs/spaces/ambassador.md"}'),n={name:"docs/spaces/ambassador.md"};function r(s,e,l,c,d,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="🚀-ambassador-module-marketing-partnership" tabindex="-1">🚀 Ambassador Module (Marketing &amp; Partnership) <a class="header-anchor" href="#🚀-ambassador-module-marketing-partnership" aria-label="Permalink to &quot;🚀 Ambassador Module (Marketing &amp; Partnership)&quot;">​</a></h1><p><strong>Ambassador</strong> is a free system tool designed to solve two key tasks for craftsmen and entrepreneurs:</p><ol><li><strong>Affiliate Income in the OmniCraft ERP Ecosystem:</strong> Recommend the software to colleagues, earn lifetime commission, and pay for subscriptions with accumulated points.</li><li><strong>Promoting Your Own Business:</strong> Smart link builder, campaign CRM tracker, and built-in AI assistant to promote your own handmade items, digital leather patterns, courses, or external software.</li></ol><hr><h2 id="💼-1-cabinet-tab-personal-profile-quick-links-links-center" tabindex="-1">💼 1. &quot;Cabinet&quot; Tab: Personal Profile, Quick Links &amp; Links Center <a class="header-anchor" href="#💼-1-cabinet-tab-personal-profile-quick-links-links-center" aria-label="Permalink to &quot;💼 1. &quot;Cabinet&quot; Tab: Personal Profile, Quick Links &amp; Links Center&quot;">​</a></h2><p>The &quot;Cabinet&quot; tab serves as the central hub of your ambassador workspace:</p><ul><li><strong>Referral Profile &amp; Dashboard:</strong> Live partnership status badge (Partner 20%, Master 30%, Legend 50%), personal referral code, progress bar towards the next tier, and real-time metrics (link clicks, 30-day sales, available balance). A single click opens the bonus redemption modal.</li><li><strong>Quick Link Generator:</strong> Instant 1-click link creation without having to set up a full campaign. Select your target page (Home, Blog, Cost Calculator, Demo, or Custom URL) — the system automatically formats tracking parameters.</li><li><strong>Links Center (Unified Directory):</strong> Complete directory of all your active links with instant filtering: <ul><li><em>All Links / ⚡ Quick Links / 📁 Campaigns;</em></li><li><em>Instant Copy:</em> Copy URLs directly to the clipboard;</li><li><em>Interactive QR Codes:</em> High-resolution QR code modal for mobile scanning and sharing;</li><li><em>Retroactive Campaign Linking:</em> Attach any standalone quick link to a campaign at any time.</li></ul></li></ul><h3 id="🧾-offline-marketing-watermark-on-electronic-receipts" tabindex="-1">🧾 Offline Marketing: Watermark on Electronic Receipts <a class="header-anchor" href="#🧾-offline-marketing-watermark-on-electronic-receipts" aria-label="Permalink to &quot;🧾 Offline Marketing: Watermark on Electronic Receipts&quot;">​</a></h3><p>Enable <strong>&quot;Place QR code on receipts&quot;</strong>, and every digital sales receipt generated in the POS terminal will include a branded referral badge with your personal QR code. Handing or sending receipts to clients organically brings in new users.</p><hr><h2 id="🌐-2-sources-tab-ai-powered-platform-discovery-channel-directory" tabindex="-1">🌐 2. &quot;Sources&quot; Tab: AI-Powered Platform Discovery &amp; Channel Directory <a class="header-anchor" href="#🌐-2-sources-tab-ai-powered-platform-discovery-channel-directory" aria-label="Permalink to &quot;🌐 2. &quot;Sources&quot; Tab: AI-Powered Platform Discovery &amp; Channel Directory&quot;">​</a></h2><p>The &quot;Sources&quot; tab helps craftsmen find their exact target audience and systematically organize marketing channels:</p><ul><li><strong>AI Platform Discovery (Interactive Strategy Chat):</strong> Ask the AI where to promote your craft (e.g., <em>&quot;Where to find custom woodworkers and leathercrafters for a cost calculator?&quot;</em>), and the strategist returns structured candidate cards.</li><li><strong>Candidate Cards:</strong> Each recommendation includes channel type (Community, Forum, Article/Blog, Video, Ad, Other), target audience profile, self-promotion rules, tone of voice, and recommended posting intervals (cooldown).</li><li><strong>Selected Bucket:</strong> Click &quot;Select&quot; to gather candidate cards into the top bucket panel, allowing you to save them all into your persistent library with a single click.</li><li><strong>Database Library:</strong> Unified catalog of verified promotional channels with search, type filters, archival support, and live campaign participation stats (e.g., <em>&quot;Habr: 3 campaigns, 2 active&quot;</em>).</li><li><strong>Full Manual Operation (BYOK):</strong> The library is fully functional for creating and managing channels manually even without configuring external AI keys.</li></ul><hr><h2 id="📣-3-campaigns-tab-source-participations-content-publishing-schedule" tabindex="-1">📣 3. &quot;Campaigns&quot; Tab: Source Participations, Content &amp; Publishing Schedule <a class="header-anchor" href="#📣-3-campaigns-tab-source-participations-content-publishing-schedule" aria-label="Permalink to &quot;📣 3. &quot;Campaigns&quot; Tab: Source Participations, Content &amp; Publishing Schedule&quot;">​</a></h2><p>The &quot;Campaigns&quot; tab coordinates target pages, promotional sources, channel-aware content creation, and publication tracking:</p><ul><li><strong>Campaigns Registry:</strong> Create and manage campaigns with target pages (Home, Blog, Calculator, Demo, or Custom URL), dates, tags, and strategic goals.</li><li><strong>Source Participations:</strong> Add verified sources from your library to any campaign (individually or in batch). Configure organic vs. paid modes, budgets, and partner contacts for each placement.</li><li><strong>Participation Lifecycle:</strong> Explicit progression across stages: <code>Candidate</code> ➔ <code>In Progress</code> ➔ <code>Published</code> ➔ <code>Completed</code>.</li><li><strong>Deterministic Link Generation:</strong> Activating a participation automatically creates a unique UTM tracking link for the exact &quot;Campaign × Source&quot; pair (with 1-click copy and QR code modal).</li><li><strong>Channel-Aware Content Generator:</strong> Generates promo materials tailored to platform rules, audience, and tone (community post, blog article, forum response, or pitch message) with A/B variant support and anti-repeat protection.</li><li><strong>Manual Mode (No AI required):</strong> Write, edit, and manage publication copy directly even without configuring AI API keys.</li><li><strong>&quot;Next Step&quot; Automation:</strong> Marking an item as published schedules follow-up actions (stats audit in 3 days, follow-up posting based on platform cooldown) with visual reminders.</li><li><strong>MCP Agent Export:</strong> Export context payloads for autonomous external AI agents in one click.</li></ul><hr><h2 id="📊-4-analytics-tab-reports-conversion-funnel-export" tabindex="-1">📊 4. &quot;Analytics&quot; Tab: Reports, Conversion Funnel &amp; Export <a class="header-anchor" href="#📊-4-analytics-tab-reports-conversion-funnel-export" aria-label="Permalink to &quot;📊 4. &quot;Analytics&quot; Tab: Reports, Conversion Funnel &amp; Export&quot;">​</a></h2><p>The &quot;Analytics&quot; tab delivers a complete overview of the performance of all your marketing campaigns and promotional channels:</p><ul><li><strong>KPI Summary Cards:</strong> Top dashboard featuring total link clicks, sign-ups (registrations), sales, earned affiliate commissions, total ad spend, and average customer acquisition cost (CAC).</li><li><strong>7 Specialized Report Views:</strong><ol><li><em>🎯 Campaign Funnels:</em> Visualizes the end-to-end customer journey (Sources ➔ Clicks ➔ Registrations ➔ Sales ➔ Revenue) with stage conversion rates ($CR_1$, $CR_2$, and overall $CR$).</li><li><em>📊 Platform Comparison:</em> Detailed table breaking down &quot;Source × Campaign&quot; pairs with mode (organic vs. paid), ad spend, clicks, sales, revenue, and direct publication URLs.</li><li><em>📑 Channel Types Breakdown:</em> Comparative analysis of communities, blog articles, craft forums, video reviews, and advertising to identify highest-ROI channels.</li><li><em>🏷️ Tag Aggregation:</em> Grouping metrics by campaign tags and thematic segments.</li><li><em>💰 Paid Channel Unit Economics (CAC):</em> Precise calculations of cost per click (CPC), cost per lead (CPA), customer acquisition cost ($CAC = \\frac{\\text{Budget}}{\\text{Sales}}$), and net profit/ROI.</li><li><em>📈 Timeline Dynamics:</em> Daily tracking of performance trends, post decay rates, and repeat promotion effects.</li><li><em>🌐 Target Pages Summary:</em> Conversion comparisons across landing pages (Home, Cost Calculator, Blog, Demo).</li></ol></li><li><strong>Data Export:</strong><ul><li><em>📥 Export CSV:</em> Download data in CSV format encoded with UTF-8 BOM for seamless viewing in spreadsheet software (Excel, Numbers, LibreOffice).</li><li><em>📋 Copy Report:</em> Copy structured tab-delimited text to the clipboard with one click.</li></ul></li><li><strong>Offline Resilience:</strong> When offline, all analytics reports are computed from local metric snapshots with an offline status banner.</li></ul><hr><h2 id="🤖-5-autonomous-digital-assistants-model-context-protocol-mcp" tabindex="-1">🤖 5. Autonomous Digital Assistants &amp; Model Context Protocol (MCP) <a class="header-anchor" href="#🤖-5-autonomous-digital-assistants-model-context-protocol-mcp" aria-label="Permalink to &quot;🤖 5. Autonomous Digital Assistants &amp; Model Context Protocol (MCP)&quot;">​</a></h2><p>The module supports native integration with external autonomous AI agents (Cursor, Antigravity, Claude Desktop) via the standard Model Context Protocol:</p><ul><li><strong>Tool Catalog:</strong> Agents are equipped with safe, sandboxed tools for querying campaigns (<code>list_campaigns</code>), KPI analytics (<code>get_stats</code>), link generation (<code>create_link</code>), and content generation (<code>generate_content</code>).</li><li><strong>Autonomy Levels:</strong> Fine-grained execution controls per platform: <ul><li><em>Draft:</em> The agent prepares structured drafts and awaits human review.</li><li><em>Semi-Auto:</em> Approved content is published automatically, stopping immediately if CAPTCHA or 2FA is encountered (Human-in-the-Loop).</li><li><em>Autopilot:</em> Restricted exclusively to explicitly trusted sources.</li></ul></li><li><strong>Audit Trail:</strong> Every tool invocation is permanently recorded in the database with timestamps, parameters, and status indicators.</li></ul><hr><h2 id="💰-6-affiliate-rewards-bonus-store" tabindex="-1">💰 6. Affiliate Rewards &amp; Bonus Store <a class="header-anchor" href="#💰-6-affiliate-rewards-bonus-store" aria-label="Permalink to &quot;💰 6. Affiliate Rewards &amp; Bonus Store&quot;">​</a></h2><p>When introducing colleagues to OmniCraft ERP, you benefit from <strong>Lifetime Attribution</strong>: you receive commissions on all subsequent subscription renewals and module purchases.</p><h3 id="commission-tiers-milestone-ladder" tabindex="-1">Commission Tiers (Milestone Ladder): <a class="header-anchor" href="#commission-tiers-milestone-ladder" aria-label="Permalink to &quot;Commission Tiers (Milestone Ladder):&quot;">​</a></h3><ul><li>🥉 <strong>Partner</strong> (base tier) ➔ <strong>20%</strong> commission</li><li>🥈 <strong>Master</strong> (10+ sales/month) ➔ <strong>30%</strong> commission</li><li>👑 <strong>Legend</strong> (50+ sales/month) ➔ <strong>50%</strong> commission</li></ul><h3 id="🎁-bonus-store-redemption" tabindex="-1">🎁 Bonus Store (Redemption): <a class="header-anchor" href="#🎁-bonus-store-redemption" aria-label="Permalink to &quot;🎁 Bonus Store (Redemption):&quot;">​</a></h3><p>Your balance is displayed on the main dashboard. Click <em>&quot;Redeem bonuses&quot;</em> to spend points on:</p><ul><li>Standard subscription renewal.</li><li>Lifetime upgrade to PRO.</li><li>Specialized marketplace modules (e.g., Pattern Module).</li></ul>',33)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
